use std :: sync :: { Arc , Mutex } ; use clap :: error :: ErrorKind ; use clap :: { Parser , Subcommand } ; use forge_api :: { AgentInfo , Model , Template } ; use forge_domain :: UserCommand ; use strum :: { EnumProperty , IntoEnumIterator } ; use strum_macros :: { EnumIter , EnumProperty } ; use crate :: info :: Info ; use std :: fmt :: Display ; use colored :: Colorize ; use console :: strip_ansi_codes ; use forge_api :: { AnyProvider , InputModality , Model , ModelId , ModelSource , ProviderId , ProviderResponse , } ; use forge_domain :: Provider ; use pretty_assertions :: assert_eq ; use url :: Url ; use super :: * ; use crate :: display_constants :: markers ; impl ForgeCommandManager { # [doc = " Sanitizes agent ID to create a valid command name"] # [doc = " Replaces spaces and special characters with hyphens"] fn sanitize_agent_id (agent_id : & str) -> String { agent_id . to_lowercase () . chars () . map (| c | if c . is_alphanumeric () { c } else { '-' }) . collect :: < String > () . split ('-') . filter (| s | ! s . is_empty ()) . collect :: < Vec < & str > > () . join ("-") } # [doc = " Checks if a command name conflicts with built-in commands"] fn is_reserved_command (name : & str) -> bool { matches ! (name , "agent" | "forge" | "muse" | "sage" | "help" | "compact" | "new" | "info" | "usage" | "exit" | "update" | "dump" | "model" | "tools" | "provider" | "login" | "logout" | "retry" | "conversations" | "list" | "commit" | "rename" | "rn" | "config" | "env" | "config-model" | "cm" | "config-reload" | "cr" | "model-reset" | "mr" | "reasoning-effort" | "re" | "config-reasoning-effort" | "cre" | "config-commit-model" | "ccm" | "config-suggest-model" | "csm" | "config-edit" | "ce" | "skill" | "edit" | "ed" | "commit-preview" | "suggest" | "s" | "clone" | "conversation-rename" | "copy" | "workspace-sync" | "sync" | "workspace-status" | "sync-status" | "workspace-info" | "sync-info" | "workspace-init" | "sync-init" | "model-test" | "mt") } fn default_commands () -> Vec < ForgeCommand > { AppCommand :: iter () . filter (| command | ! command . is_internal ()) . map (| command | ForgeCommand { name : command . name () . to_string () , description : command . usage () . to_string () , value : None , }) . collect :: < Vec < _ > > () } # [doc = " Registers workflow commands from the API."] pub fn register_all (& self , commands : Vec < forge_domain :: Command >) { let mut guard = self . commands . lock () . unwrap () ; guard . retain (| cmd | ! cmd . description . starts_with ("⚙ ")) ; let new_commands = commands . into_iter () . map (| cmd | { let name = cmd . name . clone () ; let description = format ! ("⚙ {}" , cmd . description) ; let value = cmd . prompt . clone () ; ForgeCommand { name , description , value } }) ; guard . extend (new_commands) ; guard . sort_by (| a , b | a . name . cmp (& b . name)) ; } # [doc = " Registers agent commands to the manager."] # [doc = " Returns information about the registration process."] pub fn register_agent_commands (& self , agents : Vec < AgentInfo > ,) -> AgentCommandRegistrationResult { let mut guard = self . commands . lock () . unwrap () ; let mut result = AgentCommandRegistrationResult { registered_count : 0 , skipped_conflicts : Vec :: new () } ; guard . retain (| cmd | ! cmd . name . starts_with ("agent-")) ; for agent in agents { let agent_id_str = agent . id . as_str () ; let sanitized_id = Self :: sanitize_agent_id (agent_id_str) ; let command_name = format ! ("agent-{sanitized_id}") ; if Self :: is_reserved_command (& command_name) { result . skipped_conflicts . push (command_name) ; continue ; } let default_title = agent_id_str . to_string () ; let title = agent . title . as_ref () . unwrap_or (& default_title) ; let description = format ! ("🤖 Switch to {title} agent") ; guard . push (ForgeCommand { name : command_name , description , value : Some (agent_id_str . to_string ()) , }) ; result . registered_count += 1 ; } guard . sort_by (| a , b | a . name . cmp (& b . name)) ; result } # [doc = " Finds a command by name."] fn find (& self , command : & str) -> Option < ForgeCommand > { self . commands . lock () . unwrap () . iter () . find (| c | c . name == command) . cloned () } # [doc = " Lists all registered commands."] pub fn list (& self) -> Vec < ForgeCommand > { self . commands . lock () . unwrap () . clone () } # [doc = " Extracts the command value from the input parts"] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `command` - The command for which to extract the value"] # [doc = " * `parts` - The parts of the command input after the command name"] # [doc = ""] # [doc = " # Returns"] # [doc = " * `Option<String>` - The extracted value, if any"] fn extract_command_value (& self , command : & ForgeCommand , parts : & [& str]) -> Option < String > { let value_provided = if ! parts . is_empty () { Some (parts . join (" ")) } else { None } ; let value_default = self . commands . lock () . unwrap () . iter () . find (| c | c . name == command . name) . and_then (| cmd | cmd . value . clone ()) ; match value_provided { Some (value) if ! value . trim () . is_empty () => Some (value) , _ => value_default , } } pub fn parse (& self , input : & str) -> anyhow :: Result < AppCommand > { if input . trim () . starts_with ('!') { return Ok (AppCommand :: Shell (input . strip_prefix ('!') . unwrap_or_default () . trim () . to_string () ,)) ; } let trimmed = input . trim () ; let mut tokens = trimmed . split_ascii_whitespace () ; let first = tokens . next () . unwrap_or ("") ; let is_command = first . starts_with ('/') || first . starts_with (':') ; if ! is_command { return Ok (AppCommand :: Message (input . to_string ())) ; } let bare = first . strip_prefix ('/') . or_else (| | first . strip_prefix (':')) . unwrap_or (first) ; let command_prefix = first . chars () . next () . filter (| c | * c == '/' || * c == ':') . unwrap_or (':') ; let rest : Vec < & str > = tokens . collect () ; let argv : Vec < & str > = std :: iter :: once (bare) . chain (rest . iter () . copied ()) . collect () ; let parameters : Vec < String > = rest . iter () . map (| s | s . to_string ()) . collect () ; match ClapCmd :: try_parse_from (& argv) { Ok (mut cmd) => { match & mut cmd . sub { AppCommand :: Commit { args , max_diff_size } => { * max_diff_size = args . iter () . find_map (| p | p . parse :: < usize > () . ok ()) ; } AppCommand :: Rename { name } => { let n = name . join (" ") ; let n = n . trim () . to_string () ; if n . is_empty () { return Err (anyhow :: anyhow ! ("Usage: :rename <name>. Please provide a name for the conversation.")) ; } } _ => { } } Ok (cmd . sub) } Err (clap_err) => { let command_name = bare ; if (command_name == "rename" || command_name == "rn") && rest . is_empty () { return Err (anyhow :: anyhow ! ("Usage: :rename <name>. Please provide a name for the conversation.")) ; } if command_name . starts_with ("agent-") { if let Some (found_command) = self . find (command_name) && let Some (agent_id) = & found_command . value { return Ok (AppCommand :: AgentSwitch (agent_id . clone ())) ; } return Err (anyhow :: anyhow ! ("/{command_name} is not a valid agent command")) ; } if let Some (command) = self . find (command_name) { let rest_parts : Vec < & str > = rest . to_vec () ; let template = Template :: new (self . extract_command_value (& command , & rest_parts) . unwrap_or_default () ,) ; return Ok (AppCommand :: Custom (UserCommand :: new (command . name . clone () , template , parameters ,))) ; } if clap_err . kind () == ErrorKind :: InvalidSubcommand { return Err (anyhow :: anyhow ! ("Unknown command '{command_prefix}{command_name}'. Run '{command_prefix}help' to list available commands.")) ; } let rendered = clap_err . render () . to_string () ; let cleaned = rendered . replace ("forge_cmd" , "forge") ; Err (anyhow :: anyhow ! ("{}" , cleaned . trim ())) } } } }